def read_docx_xml(path):
    with zipfile.ZipFile(path) as z:
        return z.read("word/document.xml").decode("utf-8")


def root_open_tag(xml_str):
    start = xml_str.index("<w:document")
    end = xml_str.index(">", start) + 1
    return xml_str[start:end]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true",
                     help="검증만 하고 실제 파일은 하나도 안 바꾼다")
    args = ap.parse_args()

    if not os.path.isfile(DOCX):
        print(f"FATAL: not found: {DOCX}")
        sys.exit(1)

    print(f"대상: {DOCX}")
    orig_xml = read_docx_xml(DOCX)
    orig_root_open = root_open_tag(orig_xml)

    # ---- 1) 앵커 유일성(count==1) 사전 검증 — 하나라도 실패하면 아무 것도 안 쓴다 ----
    problems = []
    if orig_xml.count(A3_ANCHOR) != 1:
        problems.append(f"A3 anchor count != 1 (got {orig_xml.count(A3_ANCHOR)})")
    for label, paraId, orig, new in EQUATIONS:
        c = orig_xml.count(orig)
        if c != 1:
            problems.append(f"eq{label} (paraId {paraId}) anchor count != 1 (got {c})")

    if problems:
        print("FATAL: 앵커 검증 실패, 아무 것도 안 씀:")
        for p in problems:
            print("  -", p)
        sys.exit(2)
    print(f"앵커 검증 통과: A3 1건 + 식 {len(EQUATIONS)}건, 전부 count==1")

    # ---- 2) 치환 적용 (메모리 안에서만, 아직 파일 안 건드림) ----
    new_xml = orig_xml.replace(A3_ANCHOR, A3_ANCHOR + A3_INSERTION, 1)
    for label, paraId, orig, new in EQUATIONS:
        before = new_xml.count(orig)
        new_xml = new_xml.replace(orig, new, 1)
        after_new = new_xml.count(new)
        if before != 1:
            print(f"FATAL: 치환 도중 eq{label} 앵커가 사라짐/중복됨 (다른 치환과 겹쳤을 가능성)")
            sys.exit(3)

    # ---- 3) 결과 검증 (파일 쓰기 전에 전부 통과해야 함) ----
    checks = []

    # 3a. well-formed XML
    try:
        new_root = ET.fromstring(new_xml)
        checks.append(("well-formed XML", True, ""))
    except Exception as e:
        checks.append(("well-formed XML", False, str(e)))
        new_root = None

    # 3b. 루트 태그(네임스페이스 선언 등) 불변
    new_root_open = root_open_tag(new_xml)
    checks.append(("루트 <w:document> 태그 불변", new_root_open == orig_root_open,
                    "" if new_root_open == orig_root_open else "루트 태그가 달라짐 — mc:Ignorable 등 확인 필요"))

    # 3c. 문단 수 기대치와 정확히 일치 (재귀 카운트: 표 안 문단 포함)
    if new_root is not None:
        old_root = ET.fromstring(orig_xml)
        old_count = len(list(old_root.iter("{%s}p" % W_NS)))
        new_count = len(list(new_root.iter("{%s}p" % W_NS)))
        delta = new_count - old_count
        checks.append((f"문단 수 델타 == {EXPECTED_PARA_DELTA} (실제 {old_count}->{new_count}, delta {delta})",
                        delta == EXPECTED_PARA_DELTA, ""))
    else:
        checks.append(("문단 수 델타 확인", False, "well-formed 실패로 건너뜀"))

    # 3d. m:oMath 삽입 개수
    omath_added = new_xml.count("<m:oMath>") - orig_xml.count("<m:oMath>")
    checks.append((f"<m:oMath> 삽입 개수 == {EXPECTED_OMATH_ADDED} (실제 {omath_added})",
                    omath_added == EXPECTED_OMATH_ADDED, ""))

    # 3e. 핵심 문자열 부재 확인 (이전 단계에서 이미 고쳤어야 하는 것들 — 회귀 방지)
    must_be_absent = [
        "our current work primarily focuses on exploiting spatial variations",
        "the carbon footprint of a job can be up to 8× higher",
        "용량을 인지하는 온라인 시간 이동의 구현은 향후 과제로 남긴다",
    ]
    for s in must_be_absent:
        checks.append((f"부재 확인: {s[:40]}...", s not in new_xml, "여전히 남아있음"))

    # 3f. 핵심 문자열 존재 확인 (이번에 새로 들어가야 하는 것들)
    must_be_present = [
        "초록", "주제어:", "Abstract", "Keywords:",
        "arg min",  # eq(9)/(14) OMML 안의 업라이트 연산자 텍스트
        # (latex2mathml 이 \argmin 내장 연산자를 렌더링할 때 arg 와 min
        #  사이에 일반 스페이스가 아니라 U+2009(THIN SPACE)를 넣는다 —
        #  실제 OMML 산출물을 확인하고 맞춘 값이다.)
    ]
    for s in must_be_present:
        checks.append((f"존재 확인: {s}", s in new_xml, "안 보임"))

    all_ok = all(ok for _, ok, _ in checks)
    print()
    print("결과 검증:")
    for name, ok, detail in checks:
        mark = "OK  " if ok else "FAIL"
        print(f"  [{mark}] {name}" + (f" — {detail}" if detail and not ok else ""))

    if not all_ok:
        print()
        print("FATAL: 검증 실패, 아무 파일도 안 씀.")
        sys.exit(4)

    if args.dry_run:
        print()
        print("--dry-run 이므로 여기서 멈춘다. 실제 파일은 하나도 안 바뀜.")
        sys.exit(0)

    # ---- 4) 스냅샷 (원자적 쓰기보다 먼저 — 실패해도 원본은 이미 안전) ----
    os.makedirs(VERSIONS_DIR, exist_ok=True)
    ts = datetime.datetime.now().strftime("%Y%m%d-%H%M")
    snapshot_path = os.path.join(VERSIONS_DIR, f"CAST_{ts}_수식초록전.docx")
    shutil.copy2(DOCX, snapshot_path)
    print(f"\n스냅샷: {snapshot_path}")

    # ---- 5) 새 docx 를 .new 경로에 원자적으로 조립 ----
    new_docx_path = DOCX + ".new"
    if os.path.exists(new_docx_path):
        os.remove(new_docx_path)

    with zipfile.ZipFile(DOCX, "r") as src, \
         zipfile.ZipFile(new_docx_path, "w", zipfile.ZIP_DEFLATED) as dst:
        for item in src.infolist():
            data = src.read(item.filename)
            if item.filename == "word/document.xml":
                data = new_xml.encode("utf-8")
            dst.writestr(item, data)

    # ---- 6) python-docx 로드 검증 (교체 전, .new 파일 대상) ----
    try:
        import docx  # python-docx
        docx.Document(new_docx_path)
        print("python-docx 로드: OK")
    except ImportError:
        print("python-docx 미설치 — 이 검증은 건너뜀(pip install python-docx 로 설치 후 재실행 권장)")
    except Exception as e:
        print(f"FATAL: python-docx 로드 실패: {e}")
        os.remove(new_docx_path)
        sys.exit(5)

    # ---- 7) 원자적 교체 ----
    os.replace(new_docx_path, DOCX)
    print(f"\n완료: {DOCX} 갱신됨. 스냅샷은 {snapshot_path} 에 보존.")
    print("Word 로 열어 육안 확인 필수 — 특히 새 5.6절 수식 15개와 표제부 초록.")


if __name__ == "__main__":
    main()
